  "ad.restart.cancel": "Cancel",
  "ad.restart.kicker": "Rewarded ad (simulation)",
  "ad.restart.title": "Ad to start over",
  "ad.title": "Try again from the checkpoint",
  "ad.watch": "Watch ad (simulate)",
  "ad.watching": "Watching ad…",
  "ch.a1": "Act I · Shadows",
  "ch.a2": "Act I · Popularity",
  "ch.a3": "Act I · Intrigue",
  "ch.b1": "Act II · Letters",
